	private static function guard() { if ( ! current_user_can( 'manage_options' ) ) wp_die( esc_html__( 'You do not have permission to view this page.', 'dsquared-hub-connector' ) ); }
	private static function wrap_start( $extra = '' ) { self::guard(); echo '<div class="wrap dhc-wrap dhc-v2 ' . esc_attr( $extra ) . '">'; }
	private static function wrap_end() { echo '</div>'; }
	private static function empty_state( $title, $body ) { echo '<div class="dhc-empty"><span class="dashicons dashicons-archive"></span><strong>' . esc_html( $title ) . '</strong><p>' . esc_html( $body ) . '</p></div>'; }
	public static function header( $icon, $title, $subtitle, $actions = '' ) { ?>
		<div class="dhc-v2-header"><div class="dhc-v2-header-copy"><span class="dhc-v2-icon dashicons <?php echo esc_attr( $icon ); ?>"></span><div><h1><?php echo esc_html( $title ); ?></h1><p><?php echo esc_html( $subtitle ); ?></p></div></div><?php if ( $actions ) : ?><div class="dhc-v2-header-actions"><?php echo $actions; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?></div><?php endif; ?></div>
	<?php }
	private static function kpi( $label, $value, $detail = '' ) { echo '<div><span>' . esc_html( $label ) . '</span><strong>' . esc_html( $value ) . '</strong>' . ( $detail ? '<small>' . esc_html( $detail ) . '</small>' : '' ) . '</div>'; }
	private static function sparkline( $values, $direction = 'up' ) {
		$values=array_values(array_filter((array)$values,'is_numeric')); if(count($values)<2)return '<span class="dhc-sparkline is-empty" aria-hidden="true"></span>';
		$min=min($values);$max=max($values);$range=max(1,$max-$min);$last=count($values)-1;$points=array();foreach($values as$i=>$value){$x=round(($i/$last)*160,1);$y=round(22-(($value-$min)/$range)*18,1);$points[]=$x.','.$y;}
		$area='0,26 '.implode(' ',$points).' 160,26';
		return '<svg class="dhc-sparkline is-'.('down'===$direction?'down':'up').'" width="160" height="26" viewBox="0 0 160 26" aria-hidden="true"><polygon points="'.esc_attr($area).'" /><polyline points="'.esc_attr(implode(' ',$points)).'" /></svg>';
	}
	private static function dashboard_kpi( $label,$value,$detail,$current,$previous,$trend=array(),$lower_better=false ) {
		$delta='';if(null!==$previous&&is_numeric($previous)){if(0.0===(float)$previous)$delta=(float)$current?'New':'No change';else{$change=$lower_better?((float)$previous-(float)$current):((float)$current-(float)$previous);$pct=abs(((float)$current-(float)$previous)/(float)$previous*100);$delta=(abs($change)<0.0001?'No change':($change>0?'↑ ':'↓ ').number_format_i18n($pct,0).'% vs prior');}}
		$direction=0===strpos($delta,'↓')?'down':'up';if(!$delta&&count((array)$trend)>1){$first=reset($trend);$last=end($trend);$direction=$lower_better?($last<=$first?'up':'down'):($last>=$first?'up':'down');}
		echo '<div class="dhc-dashboard-kpi"><span>'.esc_html($label).'</span><div class="dhc-dashboard-kpi-value"><strong>'.esc_html($value).'</strong>'.($delta?'<em class="is-'.$direction.'">'.esc_html($delta).'</em>':'').'</div>'.self::sparkline($trend,$direction).'<small>'.esc_html($detail).'</small></div>';
	}

	public static function dashboard() {
		self::wrap_start();
		$force = isset( $_POST['dhc_dashboard_action'] ) && 'refresh' === $_POST['dhc_dashboard_action'] && check_admin_referer( 'dhc_dashboard' );
		if ( $force ) DHC_Dashboard::clear_cache();
		$data = DHC_Dashboard::fetch( $force ); $days = isset( $_GET['dhc_days'] ) ? max( 7, min( 365, absint( $_GET['dhc_days'] ) ) ) : 7;
		$actions = '<select id="dhc-period-select" class="dhc-input" aria-label="Reporting period">'; foreach ( array( 7=>'Last 7 days', 28=>'Last 28 days', 90=>'Last 90 days', 365=>'Last 12 months' ) as $d=>$label ) $actions .= '<option value="' . $d . '" ' . selected( $days, $d, false ) . '>' . esc_html( $label ) . '</option>'; $actions .= '</select><a class="dhc-btn dhc-btn-outline" href="https://hub.dsquaredmedia.net" target="_blank" rel="noopener">Open Hub</a><form method="post">' . wp_nonce_field( 'dhc_dashboard', '_wpnonce', true, false ) . '<input type="hidden" name="dhc_dashboard_action" value="refresh"><button class="dhc-btn dhc-btn-outline">Refresh</button></form>';
		self::header( 'dashicons-chart-bar', 'Hub Dashboard', ! empty( $data['connected'] ) ? 'Search Console performance · last ' . $days . ' days' : 'Connect this site to see live performance.', $actions );
		$decay = get_option( 'dhc_content_decay_results', array() ); $stale = is_array( $decay['stale'] ?? null ) ? $decay['stale'] : array(); $decay_count = count( $stale );
		$modules = get_option( 'dhc_modules', array() ); $decay_enabled = ! is_array( $modules ) || ! array_key_exists( 'content_decay', $modules ) || ! empty( $modules['content_decay'] );
		if ( $decay_enabled && $decay_count ) echo '<div class="dhc-notice dhc-notice-warning"><span class="dashicons dashicons-clock"></span><div><strong>Content Decay: ' . intval( $decay_count ) . ' published posts may need review.</strong><p>These pages have not been updated in six months or show a sustained traffic decline. <a href="https://hub.dsquaredmedia.net/#content-decay" target="_blank" rel="noopener">Review them in the Hub →</a></p></div><button type="button" class="dhc-notice-dismiss" aria-label="Dismiss">×</button></div>';
		if ( empty( $data['connected'] ) ) { self::empty_state( 'Connect the Hub', $data['_error'] ?? 'Save a valid API key to load site performance.' ); self::wrap_end(); return; }
		$s = is_array( $data['summary'] ?? null ) ? $data['summary'] : array(); $previous=is_array($data['previous_summary']??null)?$data['previous_summary']:array();$trends=is_array($data['trends']??null)?$data['trends']:array();$queries = is_array( $data['top_queries'] ?? null ) ? $data['top_queries'] : array(); $pages = is_array( $data['top_pages'] ?? null ) ? $data['top_pages'] : array();
		$top3 = count( array_filter( $queries, function( $q ) { return floatval( $q['position'] ?? 99 ) <= 3.5; } ) ); $top10 = count( array_filter( $queries, function( $q ) { return floatval( $q['position'] ?? 99 ) <= 10.5; } ) ); $top = $queries[0] ?? array();
		echo '<div class="dhc-v2-kpis four dhc-dashboard-kpis">';
		self::dashboard_kpi('Clicks',number_format_i18n(intval($s['clicks_7d']??0)),'Last '.$days.' days',$s['clicks_7d']??0,$previous['clicks_7d']??null,$trends['clicks']??$trends['clicks_7d']??array());
		self::dashboard_kpi('Impressions',number_format_i18n(intval($s['impressions_7d']??0)),'Last '.$days.' days',$s['impressions_7d']??0,$previous['impressions_7d']??null,$trends['impressions']??$trends['impressions_7d']??array());
		self::dashboard_kpi('Avg position',number_format(floatval($s['avg_position']??0),1),'Across all queries',$s['avg_position']??0,$previous['avg_position']??null,$trends['avg_position']??array(),true);
		self::dashboard_kpi('CTR',number_format(floatval($s['ctr_pct']??0),2).'%','Across all queries',$s['ctr_pct']??0,$previous['ctr_pct']??null,$trends['ctr']??$trends['ctr_pct']??array());
		self::dashboard_kpi('Keywords in top 3',$top3,'Of tracked top queries',$top3,$data['previous_top3']??null,$trends['top3']??array());
		self::dashboard_kpi('Keywords in top 10',$top10,'Of tracked top queries',$top10,$data['previous_top10']??null,$trends['top10']??array());
		self::dashboard_kpi('Pages getting traffic',count($pages),'Last '.$days.' days',count($pages),$data['previous_pages_with_traffic']??null,$trends['pages']??array());
		self::dashboard_kpi('Top keyword',$top['keyword']??'—',isset($top['clicks'])?intval($top['clicks']).' clicks':'Waiting for data',$top['clicks']??0,$top['previous_clicks']??null,$top['trend']??array());echo '</div>';
		$catalog=array('phone_click'=>'Phone clicks','form_submit'=>'Form submissions','email_click'=>'Email clicks','outbound'=>'Outbound links','scroll_depth'=>'Scroll depth','video_play'=>'Video plays','cta_click'=>'CTA clicks','file_download'=>'File downloads');foreach((array)(DHC_Event_Tracker::get_config()['custom']??array())as$event)if(!empty($event['name']))$catalog[sanitize_key($event['name'])]=sanitize_text_field($event['name']);$selected=get_option('dhc_dashboard_events',array('form_submit','phone_click'));if(!is_array($selected))$selected=array();$event_data=array();foreach((array)($data['tracked_events']??$data['events']??array())as$key=>$row){if(is_array($row)){$name=sanitize_key($row['name']??$row['event']??$key);$event_data[$name]=array('value'=>intval($row['count']??$row['value']??0),'delta'=>sanitize_text_field($row['delta']??''),'trend'=>array_values(array_filter((array)($row['trend']??array()),'is_numeric')));}elseif(is_scalar($row))$event_data[sanitize_key($key)]=array('value'=>intval($row),'delta'=>'','trend'=>array());}
		echo '<section class="dhc-card dhc-events-card"><div class="dhc-card-header dhc-card-header-row"><div><h2>Tracked events</h2><p>Pick which tracked events show up here — last '.intval($days).' days.</p></div><div class="dhc-event-chooser"><button type="button" class="dhc-btn dhc-btn-outline" id="dhc-event-chooser-toggle">+ Choose events</button><div id="dhc-event-chooser-menu" class="dhc-event-chooser-menu" hidden>';foreach($catalog as$name=>$label)echo '<label><input type="checkbox" value="'.esc_attr($name).'" '.checked(in_array($name,$selected,true),true,false).'> '.esc_html($label).'</label>';echo '</div></div></div><div class="dhc-v2-kpis four dhc-event-kpis">';foreach($catalog as$name=>$label){$metric=$event_data[$name]??array('value'=>0,'delta'=>'');$direction=(preg_match('/(^|\s)(-|↓)/u',(string)$metric['delta'])?'down':'up');if(empty($metric['delta'])&&count($metric['trend']??array())>1){$first=reset($metric['trend']);$last=end($metric['trend']);$direction=$last>=$first?'up':'down';}echo '<div data-event-tile="'.esc_attr($name).'" '.(in_array($name,$selected,true)?'':'hidden').'><span>'.esc_html($label).'</span><div class="dhc-dashboard-kpi-value"><strong>'.number_format_i18n($metric['value']).'</strong>'.($metric['delta']?'<em class="is-'.$direction.'">'.esc_html($metric['delta']).'</em>':'').'</div>'.self::sparkline($metric['trend']??array(),$direction).'<small>Last '.intval($days).' days</small></div>';}echo '</div><div class="dhc-empty" id="dhc-events-empty" '.($selected?'hidden':'').'><strong>No events chosen yet</strong><p>Choose the events that matter for this site.</p></div></section>';
		if($decay_enabled){echo '<section class="dhc-card"><div class="dhc-card-header dhc-card-header-row"><div><h2>Content decay</h2><p>Pages not updated in 6+ months.</p></div><span class="dhc-status-pill is-warn">'.intval($decay_count).' stale</span></div>';if(!$stale)self::empty_state('No stale content','The daily freshness scan has not found a page needing review.');else{echo '<div class="dhc-decay-list">';foreach(array_slice($stale,0,8)as$row)echo '<div class="dhc-decay-row"><div><strong>'.esc_html($row['title']??'Untitled').'</strong><a href="'.esc_url($row['url']??'').'" target="_blank" rel="noopener">'.esc_html($row['url']??'').'</a></div><span>Last updated '.esc_html($row['last_modified']??'—').'</span></div>';echo '</div>';}echo '</section>';}
		echo '<div class="dhc-v2-grid two dhc-dashboard-detail-grid">'; self::action_plan_card($data['action_plan']??array()); self::citation_card($data['ai_citations']??array()); self::dashboard_table('Top search queries',$queries,'keyword'); self::dashboard_table('Top landing pages',$pages,'page'); echo '</div>';
		self::wrap_end();
	}
	private static function dashboard_table($title,$rows,$label_key){echo '<section class="dhc-card"><div class="dhc-card-header"><h2>'.esc_html($title).'</h2></div><div class="dhc-table-wrap">';if(empty($rows)||!is_array($rows))self::empty_state('No data yet','This panel will populate when the Hub returns measured evidence.');else{echo '<table class="dhc-v2-table"><thead><tr><th>'.('Top search queries'===$title?'Query':'Page').'</th><th>Clicks</th><th>Position</th></tr></thead><tbody>';foreach(array_slice($rows,0,6)as$row){if(!is_array($row))continue;$label=$row[$label_key]??$row['url']??$row['name']??'Item';echo '<tr><td><strong>'.esc_html($label).'</strong></td><td>'.esc_html(number_format_i18n(intval($row['clicks']??0))).'</td><td>'.(isset($row['position'])?esc_html(number_format_i18n((float)$row['position'],1)):'—').'</td></tr>';}echo '</tbody></table>';}echo '</div></section>';}
	private static function action_plan_card($rows){echo '<section class="dhc-card"><div class="dhc-card-header"><h2>Content actions from Action Plan</h2><p>Work the Hub has prepared for this site.</p></div>';if(empty($rows)||!is_array($rows))self::empty_state('No actions ready','Approved content actions will appear here.');else{echo '<div class="dhc-action-list">';foreach(array_slice($rows,0,6)as$row){if(!is_array($row))continue;$title=$row['title']??$row['name']??'Content action';$status=$row['status']??'Ready for review';$url=$row['push_url']??$row['url']??'';echo '<div class="dhc-action-row"><div><strong>'.esc_html($title).'</strong><small>'.esc_html($status).'</small></div>'.($url?'<a class="dhc-btn dhc-btn-small" href="'.esc_url($url).'">'.(!empty($row['push_url'])?'Push to WordPress':'Review').'</a>':'<span class="dhc-status-pill">'.esc_html($status).'</span>').'</div>';}echo '</div>';}echo '</section>';}
	private static function citation_card($rows){echo '<section class="dhc-card"><div class="dhc-card-header"><h2>AI citations</h2><p>Mentions of this website in monitored AI answers.</p></div><div class="dhc-table-wrap">';if(empty($rows)||!is_array($rows))self::empty_state('No citations measured','Citation counts appear after the Hub completes an AI Visibility scan.');else{echo '<table class="dhc-v2-table"><thead><tr><th>Engine</th><th>Citations</th><th>Vs. prior</th></tr></thead><tbody>';foreach(array_slice($rows,0,6)as$row){if(!is_array($row))continue;echo '<tr><td><strong>'.esc_html($row['engine']??$row['name']??'AI engine').'</strong></td><td>'.esc_html(number_format_i18n(intval($row['citations']??$row['count']??$row['value']??0))).'</td><td>'.esc_html($row['delta']??'—').'</td></tr>';}echo '</tbody></table>';}echo '</div></section>';}

	public static function connection() {
		self::wrap_start(); $has_api_key = '' !== (string) get_option( 'dhc_api_key', '' ); $sub = DHC_API_Key::validate(); $status = ! empty( $sub['valid'] ) ? 'Connected' : ( ! empty( $sub['expired'] ) ? 'Expired' : 'Not connected' );
		self::header( 'dashicons-admin-network', 'API Connection', 'Connect this WordPress site to your Dsquared Media Hub account.', '<span class="dhc-status-pill ' . ( 'Connected' === $status ? 'is-good' : 'is-warn' ) . '">' . esc_html( $status ) . '</span><button type="button" id="dhc-refresh-connection" class="dhc-btn dhc-btn-outline">Refresh</button><a class="dhc-btn dhc-btn-outline" href="https://hub.dsquaredmedia.net/#account" target="_blank" rel="noopener">Open Hub</a>' ); ?>
		<section class="dhc-card"><div class="dhc-card-header"><h2>API connection</h2><p>Connect this WordPress site to your Dsquared Media Hub account.</p></div><div class="dhc-card-body"><label class="dhc-v2-field"><span>API key</span><div class="dhc-v2-input-row"><input type="password" id="dhc-api-key" class="dhc-input" value="" data-has-key="<?php echo $has_api_key ? '1' : '0'; ?>" placeholder="<?php echo esc_attr( $has_api_key ? 'Connected — paste a replacement key' : 'Enter your Hub API key' ); ?>" autocomplete="new-password"></div></label><div class="dhc-actions"><button type="button" class="dhc-btn dhc-btn-primary" id="dhc-save-key">Save &amp; Validate</button><span id="dhc-key-status" class="dhc-status-msg" role="status"></span></div></div></section>
		<div class="dhc-notice dhc-notice-danger"><span class="dashicons dashicons-warning"></span><div><strong>Do not deactivate this plugin.</strong><p>Deactivating turns off schema, redirects, tracking, lead forwarding and every Hub feature at once. A lapsed subscription leaves the plugin active and only pauses Hub services.</p></div></div>
		<section class="dhc-card"><div class="dhc-card-header"><h2>Subscription details</h2></div><div class="dhc-card-body"><div class="dhc-v2-kpis three"><?php self::kpi( 'Status', $status ); self::kpi( 'WordPress', get_bloginfo( 'version' ) ); self::kpi( 'SEO plugin', defined( 'WPSEO_VERSION' ) ? 'Yoast' : ( defined( 'RANK_MATH_VERSION' ) ? 'Rank Math' : 'Auto-detected' ) ); self::kpi( 'REST endpoint', rest_url( 'dsquared-hub/v1/' ) ); self::kpi( 'Hub scan worker', $sub['scan_worker'] ?? 'Not reported' ); self::kpi( 'Last scan check', $sub['last_scan_check'] ?? 'Not checked' ); ?></div></div></section>
		<?php $remaining=$sub['credits_remaining']??null;$monthly=$sub['credits_monthly']??null;$pct=(null!==$remaining&&$monthly)?min(100,round(($remaining/$monthly)*100)):0; ?>
		<section class="dhc-card"><div class="dhc-card-header"><h2>Credit balance</h2></div><div class="dhc-card-body"><div class="dhc-credit-row"><div><strong><?php echo null===$remaining?'—':number_format_i18n($remaining); ?></strong><span> remaining<?php echo null===$monthly?'':' of '.esc_html(number_format_i18n($monthly)).' monthly'; ?></span></div><a href="https://hub.dsquaredmedia.net/#credits" target="_blank" rel="noopener">Buy more credits →</a></div><div class="dhc-progress"><span style="width:<?php echo esc_attr($pct); ?>%"></span></div><p>Scans, generated drafts and alt-text generations draw from this website’s balance.</p></div></section><?php self::wrap_end();
	}

