	public static function site_health() {
		self::wrap_start(); self::header('dashicons-heart','Site Health','Core Web Vitals and real-user performance.'); $m=DHC_Site_Health::get_aggregated_metrics(30); $defs=array('lcp_p75'=>array('LCP','Largest Contentful Paint','2.5s'),'cls_p75'=>array('CLS','Cumulative Layout Shift','0.1'),'inp_p75'=>array('INP','Interaction to Next Paint','200ms'),'ttfb_p75'=>array('TTFB','Time to First Byte','800ms'),'fid_p75'=>array('FID','First Input Delay','100ms')); echo '<section class="dhc-card"><div class="dhc-card-header"><h2>Core Web Vitals — last 30 days</h2><p>Real-user metrics (75th percentile)</p></div><div class="dhc-card-body"><div class="dhc-v2-kpis five">'; foreach($defs as $key=>$d){$v=$m[$key]??null;$metric=str_replace('_p75','',$key);$rating=null===$v?'unknown':DHC_Site_Health::get_rating($metric,$v);$display=null===$v?'—':('lcp'===$metric?number_format($v/1000,1).'s':('cls'===$metric?number_format($v,2):round($v).'ms'));echo '<div class="'.('good'===$rating?'is-good':(('poor'===$rating||'bad'===$rating)?'is-bad':'')).'"><span>'.esc_html($d[0]).'</span><strong>'.esc_html($display).'</strong><small>'.esc_html($d[1].' · Good ≤ '.$d[2].' · '.$rating).'</small></div>';} echo '</div><p style="text-align:center;color:var(--dhc-muted);margin:12px 0 0">'.intval($m['count']??0).' page loads measured</p></div></section>'; self::wrap_end();
	}

	private static function discovery_content($file){$path=ABSPATH.$file;if(is_readable($path))return (string)file_get_contents($path);if('robots.txt'===$file)return apply_filters('robots_txt',"User-agent: *\nDisallow:\n",true);if(class_exists('DHC_AI_Discovery')){$r=DHC_AI_Discovery::init()->render_files();$key='llms-full.txt'===$file?'llms_full':'llms';return (string)($r[$key]??'');}return '';}

	private static function robots_directives_valid( $body ) {
		$active_group = false; $seen_agent = false; $group_directives=array('allow','disallow');$global_directives=array('sitemap','host','crawl-delay','request-rate','clean-param');
		foreach ( preg_split( '/\R/', (string) $body ) as $line ) {
			$line = trim( preg_replace( '/\s*#.*$/', '', $line ) );
			if ( '' === $line ) { $active_group = false; continue; }
			if(!preg_match('/^([A-Za-z][A-Za-z-]*)\s*:\s*(.*)$/',$line,$parts))return false;$directive=strtolower($parts[1]);$value=trim($parts[2]);
			if('user-agent'===$directive){if(''===$value)return false;$active_group=true;$seen_agent=true;continue;}
			if(in_array($directive,$global_directives,true))continue;
			if(!in_array($directive,$group_directives,true)||!$active_group)return false;
		}
		return $seen_agent;
	}

	private static function live_check( $live, $key, $title ) {
		if ( ! isset( $live[ $key ] ) || ! is_array( $live[ $key ] ) ) return array( $title, null, 'Unknown — run Re-check to collect live HTTP evidence.' );
		return array( $title, ! empty( $live[ $key ]['ok'] ), sanitize_text_field( $live[ $key ]['message'] ?? '' ) );
	}

	public static function indexing() {
		self::wrap_start();
		$live = get_option( 'dhc_indexing_live_validation', array() ); if ( ! is_array( $live ) ) $live = array();
		$key = get_option( 'dhc_indexnow_key', '' ); $last = intval( get_option( DHC_AI_Discovery::INDEXNOW_LAST_OPTION, 0 ) ); $last_status = intval( get_option( 'dhc_indexnow_last_status', 0 ) );
		self::header('dashicons-networking','Indexing','llms.txt, robots.txt, and IndexNow — what AI engines and search bots see.','<button type="button" id="dhc-recheck-indexing" class="dhc-btn dhc-btn-outline">Re-check</button><button type="button" id="dhc-submit-indexnow-all" class="dhc-btn dhc-btn-primary">Submit to IndexNow now</button>');
		$checks = array(
			self::live_check( $live, 'robots', 'robots.txt response and directive groups' ),
			self::live_check( $live, 'encoding', 'llms.txt response and UTF-8 encoding' ),
			self::live_check( $live, 'links', 'llms.txt Markdown links' ),
			self::live_check( $live, 'key', 'IndexNow key file' ),
		);
		$known = count( array_filter( $checks, function( $check ) { return null !== $check[1]; } ) );
		$pass = count( array_filter( $checks, function( $check ) { return true === $check[1]; } ) );
		$summary = $known ? $pass . ' / ' . $known . ' passing' : 'Unknown';
		echo '<section class="dhc-card"><div class="dhc-card-header"><h2>Live validation <span class="dhc-status-pill '.(4===$pass?'is-good':($known?'is-warn':'is-unknown')).'">'.esc_html($summary).'</span></h2><p>'.(!empty($live['checked_at'])?'Checked '.esc_html($live['checked_at']):'No live HTTP check has been recorded yet.').'</p></div><div class="dhc-card-body">';
		foreach ( $checks as $check ) { $class = null === $check[1] ? 'is-unknown' : ( $check[1] ? 'is-good' : 'is-bad' ); $icon = null === $check[1] ? 'dashicons-minus' : ( $check[1] ? 'dashicons-yes-alt' : 'dashicons-warning' ); echo '<div class="dhc-check-row '.$class.'"><span class="dashicons '.$icon.'"></span><div><strong>'.esc_html($check[0]).'</strong><br><small>'.esc_html($check[2]).'</small></div></div>'; }
		echo '<span id="dhc-indexing-check-status" class="dhc-status-msg"></span></div></section>';
		echo '<section class="dhc-card"><div class="dhc-card-header"><h2>Sitemaps</h2><p>Only sitemap files confirmed live in the latest HTTP check are listed.</p></div><div class="dhc-table-wrap">';
		$sitemaps=(array)($live['sitemaps']??array());if(!$sitemaps)self::empty_state('No published sitemap detected','Run Re-check. The Hub will test the robots.txt declarations and common WordPress sitemap providers.');else{echo '<table class="dhc-v2-table"><thead><tr><th>Endpoint</th><th>Contents</th><th>Last modified</th><th>Status</th></tr></thead><tbody>';foreach($sitemaps as$row){$kind='sitemapindex'===($row['kind']??'')?'sub-sitemaps':'URLs';$parent=!empty($row['parent'])?'<small>Child of '.esc_html(wp_parse_url($row['parent'],PHP_URL_PATH)).'</small>':'';echo '<tr><td><a href="'.esc_url($row['url']??'').'" target="_blank" rel="noopener">'.esc_html($row['url']??'').'</a>'.$parent.'</td><td>'.intval($row['count']??0).' '.esc_html($kind).'</td><td>'.esc_html(($row['lastmod']??'')?:'Not provided').'</td><td><span class="dhc-status-pill is-good">HTTP 200</span></td></tr>';}echo '</tbody></table>';}
		echo '</div></section>';
		foreach(array('robots.txt','llms.txt') as $file){$id='dhc-file-'.sanitize_key($file);echo '<section class="dhc-card"><div class="dhc-card-header"><h2>'.esc_html($file).'</h2><p>Generated content preview — live response is verified only by Re-check.</p></div><div class="dhc-card-body"><button type="button" class="dhc-btn dhc-btn-outline" data-file-edit="'.esc_attr($id).'">Edit</button><pre class="dhc-preview">'.esc_html(self::discovery_content($file)).'</pre><div class="dhc-file-edit" id="'.esc_attr($id).'" hidden><div class="dhc-notice dhc-notice-danger"><strong>This is dangerous.</strong><p>A malformed '.esc_html($file).' can hide the site from search or AI systems.</p></div><textarea rows="12">'.esc_textarea(self::discovery_content($file)).'</textarea><div class="dhc-actions"><button type="button" class="dhc-btn dhc-btn-outline" data-file-cancel="'.esc_attr($id).'">Cancel</button><button type="button" class="dhc-btn dhc-btn-primary" data-file-save="'.esc_attr($file).'">Save changes</button></div></div></div></section>';}
		echo '<div class="dhc-v2-grid two"><section class="dhc-card"><div class="dhc-card-header"><h2>IndexNow</h2></div><div class="dhc-card-body"><div class="dhc-v2-kpis three">';self::kpi('Key file',$key?'Configured':'Missing');self::kpi('Last submitted',$last?wp_date('M j, Y g:i a',$last):'Never');self::kpi('Response code',$last_status?:'—');echo '</div><span id="dhc-indexnow-status" class="dhc-status-msg"></span></div></section><section class="dhc-card"><div class="dhc-card-header"><h2>Generated AI discovery files</h2></div><div class="dhc-card-body"><p><a href="'.esc_url(home_url('/llms.txt')).'" target="_blank">'.esc_html(home_url('/llms.txt')).'</a></p><p><a href="'.esc_url(home_url('/llms-full.txt')).'" target="_blank">'.esc_html(home_url('/llms-full.txt')).'</a></p><p>IndexNow key: <code>'.esc_html($key?:'Not generated').'</code></p></div></section></div>';
		self::wrap_end();
	}

