	private static function link_table($title,$rows,$is404){echo '<section class="dhc-card"><div class="dhc-card-header"><h2>'.esc_html($title).'</h2></div><div class="dhc-table-wrap">';if(empty($rows))self::empty_state('Nothing found',$is404?'Real visitor 404s will appear here.':'The last scan found no broken links.');else{echo '<table class="dhc-v2-table"><thead><tr><th>'.($is404?'Path':'URL').'</th><th>'.($is404?'Hits':'Status').'</th><th>'.($is404?'Last seen':'Found on').'</th><th></th></tr></thead><tbody>';foreach($rows as $row){$url=$row[$is404?'path':'url']??'';echo '<tr><td>'.esc_html($url).'</td><td>'.esc_html($is404?($row['count']??1):($row['status']??'—')).'</td><td>'.esc_html($is404?($row['last_seen']??'—'):($row['source_title']??$row['source']??'—')).'</td><td><a href="'.esc_url(admin_url('admin.php?page=dsquared-hub-redirects&from='.rawurlencode($url))).'">+ Add redirect</a></td></tr>';}echo '</tbody></table>';}echo '</div></section>';}

