-btn-small" data-redirect="'.esc_attr($json).'">Edit</button><button type="button" class="dhc-redirect-delete dhc-btn dhc-btn-small" data-id="'.esc_attr($row['id']??'').'">Delete</button></td></tr>';}echo '</tbody></table>';}echo '</div></section>';self::wrap_end();}

	public static function forms(){
		self::wrap_start();
		$rows=DHC_Form_Capture::get_submissions();
		$spam=count(array_filter($rows,function($r){return!empty($r['spam']);}));
		$plugins=array_unique(array_filter(array_column($rows,'form_plugin')));
		$export=wp_nonce_url(admin_url('admin-post.php?action=dhc_form_export'),'dhc_form_export');
		self::header('dashicons-feedback','Forms','Submissions captured across supported form plugins on this site.','<a id="dhc-form-export" class="dhc-btn dhc-btn-outline" href="'.esc_url($export).'">Export CSV</a>');
		echo '<div class="dhc-v2-kpis three">'; self::kpi('Submissions',count($rows)); self::kpi('Marked as spam',$spam); self::kpi('Form plugins detected',count($plugins)); echo '</div>';
		echo '<section class="dhc-card"><div class="dhc-card-body">Every submission also fires a <code>form_submit</code> event automatically — <a href="'.esc_url(admin_url('admin.php?page=dsquared-hub-events')).'">see Event Tracking</a>.</div></section>';
		echo '<div class="dhc-filter-tabs"><button class="is-active" data-form-filter="all">All ('.count($rows).')</button><button data-form-filter="spam">Spam ('.$spam.')</button></div><section class="dhc-card"><div class="dhc-table-wrap">';
		if(empty($rows)){self::empty_state('No submissions yet','New supported form submissions will appear here and continue forwarding to the Hub.');}
		else{
			echo '<table class="dhc-v2-table"><thead><tr><th>Name</th><th>Email</th><th>Form</th><th>Page</th><th>IP address</th><th>Received</th><th></th></tr></thead><tbody>';
			foreach($rows as$row){
				$is_spam=!empty($row['spam']); $plugin=$row['form_plugin']??''; $class=stripos($plugin,'gravity')!==false?'gravity':(stripos($plugin,'wpforms')!==false?'wpforms':(stripos($plugin,'elementor')!==false?'elementor':''));
				echo '<tr data-form-row="'.($is_spam?'spam':'inbox').'" data-form-detail="'.esc_attr(wp_json_encode($row)).'"><td><strong>'.esc_html($row['name']?:'Anonymous').'</strong></td><td>'.esc_html($row['email']??'—').'</td><td><span class="dhc-plugin-badge '.esc_attr($class).'">'.esc_html($plugin?:$row['form_name']??'Form').'</span></td><td><a href="'.esc_url($row['source_url']??'').'" target="_blank">'.esc_html(wp_parse_url($row['source_url']??'',PHP_URL_PATH)?:'/').'</a></td><td>'.esc_html($row['ip_address']??'—').'</td><td>'.esc_html($row['created_at']??'').'</td><td class="dhc-table-actions"><button type="button" class="dhc-form-view dhc-btn dhc-btn-small">View</button><button type="button" class="dhc-spam-toggle dhc-btn dhc-btn-small '.($is_spam?'is-warn':'').'" data-id="'.esc_attr($row['id']??'').'" data-spam="'.($is_spam?'0':'1').'">'.($is_spam?'Not spam':'Mark spam').'</button></td></tr>';
			}
