	public static function ajax_recheck_indexing(){
		check_ajax_referer('dhc_admin_nonce','nonce');
		if(!current_user_can('manage_options'))wp_send_json_error('Forbidden.',403);
		if(!DHC_API_Key::is_module_available('ai_discovery'))wp_send_json_error('AI Discovery is unavailable on the current subscription.',403);
		$key=(string)get_option('dhc_indexnow_key','');
		$fetch=function($url,$method='GET'){
			$args=array('timeout'=>12,'redirection'=>3,'user-agent'=>'DsquaredHubConnector/'.DHC_VERSION.' (indexing-validator)');
			$response='HEAD'===$method?wp_safe_remote_head($url,$args):wp_safe_remote_get($url,$args);
			if(is_wp_error($response))return array('code'=>0,'type'=>'','body'=>'','message'=>$response->get_error_message());
			return array('code'=>intval(wp_remote_retrieve_response_code($response)),'type'=>strtolower(trim((string)wp_remote_retrieve_header($response,'content-type'))),'body'=>(string)wp_remote_retrieve_body($response),'message'=>'');
		};
		$robots=$fetch(home_url('/robots.txt'));
		$llms=$fetch(home_url('/llms.txt'));
		$key_file=$key?$fetch(home_url('/'.$key.'.txt')):array('code'=>0,'type'=>'','body'=>'','message'=>'No key configured.');
		$robots_type=false!==strpos($robots['type'],'text/plain');
		$robots_body=''!==trim($robots['body']);
		$robots_rules=$robots_body&&self::robots_directives_valid($robots['body']);
		$llms_type=false!==strpos($llms['type'],'text/plain');
		$llms_utf8=(bool)preg_match('/charset\s*=\s*["\']?utf-8/i',$llms['type']);
		$llms_body=''!==trim($llms['body'])&&false===strpos($llms['body'],'â');
		preg_match_all('/\[[^\]]+\]\((https?:\/\/[^)\s]+)\)/i',$llms['body'],$matches);
		$links=array_values(array_unique($matches[1]??array())); $bad_links=array();
		foreach($links as$url){$r=$fetch($url,'HEAD');if(200!==$r['code'])$r=$fetch($url);if(200!==$r['code'])$bad_links[]=array('url'=>$url,'code'=>$r['code']);}
		$key_type=false!==strpos($key_file['type'],'text/plain');
		$checks=array(
			'robots'=>array('ok'=>200===$robots['code']&&$robots_type&&$robots_body&&$robots_rules,'message'=>'HTTP '.$robots['code'].' · '.($robots_type?'text/plain':'wrong Content-Type').' · '.($robots_rules?'directive groups valid':'invalid directive grouping')),
			'encoding'=>array('ok'=>200===$llms['code']&&$llms_type&&$llms_utf8&&$llms_body,'message'=>'HTTP '.$llms['code'].' · '.($llms['type']?:'missing Content-Type').' · '.($llms_body?'body readable':'body empty or misencoded')),
			'links'=>array('ok'=>!empty($links)&&empty($bad_links),'message'=>empty($links)?'No Markdown links found':(empty($bad_links)?count($links).' Markdown links returned HTTP 200':count($bad_links).' of '.count($links).' links did not return HTTP 200')),
			'key'=>array('ok'=>200===$key_file['code']&&$key_type&&trim($key_file['body'])===$key,'message'=>$key_file['message']?:'HTTP '.$key_file['code'].' · '.($key_type?'text/plain':'wrong Content-Type').' · '.(trim($key_file['body'])===$key?'body matches':'body mismatch')),
			'bad_links'=>$bad_links,
			'sitemaps'=>array(),
			'checked_at'=>current_time('mysql'),
		);
		$checks['sitemaps']=self::discover_published_sitemaps($fetch,$robots['body']);
		update_option('dhc_indexing_live_validation',$checks,false);
		wp_send_json_success($checks);
	}

	/** Parse a real XML sitemap document and reject HTML wrappers or malformed children. */
	private static function parse_sitemap_document($body){
		if(!is_string($body)||''===trim($body)||!class_exists('DOMDocument'))return null;
		$previous=libxml_use_internal_errors(true);libxml_clear_errors();$document=new DOMDocument();
		$loaded=$document->loadXML(trim($body),LIBXML_NONET|LIBXML_NOBLANKS|LIBXML_COMPACT);$errors=libxml_get_errors();libxml_clear_errors();libxml_use_internal_errors($previous);
		if(!$loaded||!empty($errors)||!$document->documentElement)return null;
		$root=$document->documentElement;$kind=strtolower((string)$root->localName);
		if(!in_array($kind,array('sitemapindex','urlset'),true))return null;
		$official='http://www.sitemaps.org/schemas/sitemap/0.9';$namespace=rtrim((string)$root->namespaceURI,'/');if($official!==$namespace)return null;
		$tag='sitemapindex'===$kind?'sitemap':'url';$entries=array();
		foreach($root->childNodes as$node){if(XML_ELEMENT_NODE!==$node->nodeType)continue;if($official!==rtrim((string)$node->namespaceURI,'/')||strtolower((string)$node->localName)!==$tag)return null;$loc='';$lastmod='';$loc_count=0;
			foreach($node->childNodes as$child){if(XML_ELEMENT_NODE!==$child->nodeType)continue;$name=strtolower((string)$child->localName);$child_namespace=rtrim((string)$child->namespaceURI,'/');if('loc'===$name){if($official!==$child_namespace)return null;$loc=trim($child->textContent);$loc_count++;}elseif('lastmod'===$name){if($official!==$child_namespace)return null;$lastmod=trim($child->textContent);}elseif(in_array($name,array('changefreq','priority'),true)&&$official!==$child_namespace)return null;}
			if(1!==$loc_count||!filter_var($loc,FILTER_VALIDATE_URL)||!in_array(strtolower((string)wp_parse_url($loc,PHP_URL_SCHEME)),array('http','https'),true))return null;
			$entries[]=array('url'=>$loc,'lastmod'=>$lastmod);
		}
		$lastmods=array_values(array_filter(array_column($entries,'lastmod')));sort($lastmods,SORT_STRING);
		return array('kind'=>$kind,'count'=>count($entries),'lastmod'=>$lastmods?end($lastmods):'','entries'=>$entries);
	}

	private static function same_site_url($url){$home=wp_parse_url(home_url('/'));$candidate=wp_parse_url($url);if(!is_array($home)||!is_array($candidate))return false;$scheme=strtolower($candidate['scheme']??'');$home_scheme=strtolower($home['scheme']??'');$port=intval($candidate['port']??('https'===$scheme?443:80));$home_port=intval($home['port']??('https'===$home_scheme?443:80));return in_array($scheme,array('http','https'),true)&&$scheme===$home_scheme&&strtolower($candidate['host']??'')===strtolower($home['host']??'')&&$port===$home_port;}

	/** Discover only sitemap endpoints that are actually published and parse their children. */
	private static function discover_published_sitemaps($fetch,$robots_body=''){
		$candidates=array();preg_match_all('/^\s*Sitemap\s*:\s*(\S+)/mi',(string)$robots_body,$declared);foreach($declared[1]??array()as$url)$candidates[]=$url;$candidates[]=home_url('/wp-sitemap.xml');$candidates[]=home_url('/sitemap_index.xml');$candidates=array_values(array_unique(array_filter($candidates,array(__CLASS__,'same_site_url'))));$rows=array();$seen=array();
		$inspect=function($url,$parent='')use(&$inspect,&$rows,&$seen,$fetch){if(isset($seen[$url])||!self::same_site_url($url))return;$seen[$url]=true;$response=$fetch($url);if(200!==intval($response['code']??0))return;$parsed=self::parse_sitemap_document($response['body']??'');if(!$parsed)return;$rows[]=array('url'=>$url,'code'=>200,'kind'=>$parsed['kind'],'count'=>$parsed['count'],'lastmod'=>$parsed['lastmod'],'parent'=>$parent);if('sitemapindex'===$parsed['kind'])foreach($parsed['entries']as$entry)$inspect($entry['url'],$url);};
		foreach($candidates as$url)$inspect($url);return $rows;
	}

	public static function ajax_save_profile(){check_ajax_referer('dhc_admin_nonce','nonce');if(!current_user_can('manage_options'))wp_send_json_error('Forbidden.',403);if(!DHC_API_Key::is_module_available('schema')&&!DHC_API_Key::is_module_available('ai_discovery'))wp_send_json_error('Schema and AI Discovery are unavailable on the current subscription.',403);$incoming=json_decode(wp_unslash($_POST['profile']??''),true);if(!is_array($incoming))wp_send_json_error('Invalid profile.',400);$allowed=array('notes');foreach(self::profile_fields()as$section)$allowed=array_merge($allowed,array_keys($section[2]));$clean=array();foreach($allowed as$key){if(!array_key_exists($key,$incoming))continue;$clean[$key]=$incoming[$key];}$clean=class_exists('DHC_AI_Discovery')?DHC_AI_Discovery::save_business_profile_data($clean):$clean;if(!class_exists('DHC_AI_Discovery'))update_option('dhc_business_profile',$clean,false);$discovery_saved=false;$settings=json_decode(wp_unslash($_POST['settings']??'{}'),true);if(class_exists('DHC_AI_Discovery')&&DHC_API_Key::is_module_available('ai_discovery')){if(is_array($settings))DHC_AI_Discovery::init()->save_editor_settings($settings,'admin');else DHC_AI_Discovery::regenerate_files($clean);$discovery_saved=true;}DHC_Event_Logger::log('business_profile_saved','ai_discovery',array('fields'=>count(array_filter($clean))),'Business profile updated.');wp_send_json_success(array('message'=>$discovery_saved?'Business profile saved and discovery files regenerated.':'Business profile saved.'));}
	public static function ajax_save_discovery_file(){check_ajax_referer('dhc_admin_nonce','nonce');if(!current_user_can('manage_options'))wp_send_json_error('Forbidden.',403);if(!DHC_API_Key::is_module_available('ai_discovery'))wp_send_json_error('AI Discovery is unavailable on the current subscription.',403);$file=sanitize_file_name(wp_unslash($_POST['file']??''));if(!in_array($file,array('robots.txt','llms.txt'),true))wp_send_json_error('Unsupported file.',400);$content=str_replace("\r\n","\n",wp_unslash($_POST['content']??''));if(strlen($content)>500000)wp_send_json_error('File is too large.',400);if('robots.txt'===$file&&!self::robots_directives_valid($content))wp_send_json_error('robots.txt must contain valid line-by-line directive groups. Put crawler rules after a User-agent line.',400);$ok=@file_put_contents(ABSPATH.$file,$content,LOCK_EX);if(false===$ok)wp_send_json_error('WordPress could not write the file. Check filesystem permissions.',500);DHC_Event_Logger::log('discovery_file_saved','ai_discovery',array('file'=>$file),'Updated '.$file.'.');wp_send_json_success(array('message'=>$file.' saved.','content'=>$content));}
	private static function upsert_picker_event($rows,$event){$name=sanitize_key($event['name']??'');$clean=array();foreach((array)$rows as$row){if(sanitize_key($row['name']??'')===$name)continue;$clean[]=$row;}$clean[]=$event;return array_values($clean);}
	public static function ajax_save_picker_event(){check_ajax_referer('dhc_admin_nonce','nonce');if(!current_user_can('manage_options'))wp_send_json_error('Forbidden.',403);$name=sanitize_key(wp_unslash($_POST['name']??''));$selector=sanitize_text_field(wp_unslash($_POST['selector']??''));$trigger=sanitize_key(wp_unslash($_POST['trigger']??'click'));if(!$name||!$selector||strlen($selector)>500||!in_array($trigger,array('click','view','hover'),true))wp_send_json_error('Enter a valid event name and selector.',400);$cfg=DHC_Event_Tracker::get_config();$event=array('name'=>$name,'selector'=>$selector,'trigger'=>$trigger);$cfg['custom']=self::upsert_picker_event($cfg['custom']??array(),$event);update_option(DHC_Event_Tracker::OPT,$cfg,false);DHC_Event_Logger::log('custom_event_saved','event_tracking',array('name'=>$name),'Added custom event '.$name.'.');wp_send_json_success(array('event'=>$event));}
