	public static function export_activity(){if(!current_user_can('manage_options'))wp_die('Forbidden.',403);check_admin_referer('dhc_activity_export');nocache_headers();header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="d2-activity-'.gmdate('Y-m-d').'.csv"');$out=fopen('php://output','w');fputcsv($out,array('User','Email','IP address','What changed','When'));foreach(get_option('dhc_activity_log',array())as$row)fputcsv($out,array($row['user']??'',$row['email']??'',$row['ip']??'',$row['message']??$row['action']??'',$row['time']??''));fclose($out);exit;}
